datasource db {
  provider = "sqlite"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

model User {
  id       Int       @id @default(autoincrement())
  username String    @unique
  comments Comment[]
}

model Post {
  id       Int       @id @default(autoincrement())
  title    String
  comments Comment[]
}

model Comment {
  id             Int       @id @default(autoincrement())
  content        String
  postId         Int
  post           Post      @relation(fields: [postId], references: [id], onDelete: Cascade)
  authorId       Int
  author         User      @relation(fields: [authorId], references: [id], onDelete: Cascade)
  parentId       Int?
  parent         Comment?  @relation("CommentReplies", fields: [parentId], references: [id], onDelete: Cascade)
  children       Comment[] @relation("CommentReplies")
}

interface GetCommentTreeArgs {
  postId: number;
}

interface CommentNode {
  id: number;
  content: string;
  authorUsername: string;
  parentId: number | null;
  children: CommentNode[];
}

export const getPosts = async (args: void, context: { entities: { Post: any } }) => {
  return context.entities.Post.findMany({
    select: {
      id: true,
      title: true
    }
  });
};

export const getCommentTree = async (
  args: GetCommentTreeArgs,
  context: { entities: { Comment: any } }
): Promise<CommentNode[]> => {
  const { postId } = args;

  const comments = await context.entities.Comment.findMany({
    where: { postId },
    include: {
      author: true
    },
    orderBy: {
      id: 'asc'
    }
  });

  const nodeMap = new Map<number, CommentNode>();

  for (const comment of comments) {
    nodeMap.set(comment.id, {
      id: comment.id,
      content: comment.content,
      authorUsername: comment.author.username,
      parentId: comment.parentId,
      children: []
    });
  }

  const rootNodes: CommentNode[] = [];

  for (const comment of comments) {
    const node = nodeMap.get(comment.id)!;
    if (comment.parentId === null) {
      rootNodes.push(node);
    } else {
      const parentNode = nodeMap.get(comment.parentId);
      if (parentNode) {
        parentNode.children.push(node);
      } else {
        rootNodes.push(node);
      }
    }
  }

  const sortChildren = (node: CommentNode) => {
    node.children.sort((a, b) => a.id - b.id);
    node.children.forEach(sortChildren);
  };

  rootNodes.sort((a, b) => a.id - b.id);
  rootNodes.forEach(sortChildren);

  return rootNodes;
};

interface CreateCommentArgs {
  postId: number;
  authorUsername: string;
  content: string;
  parentId?: number | null;
}

interface DeleteCommentArgs {
  commentId: number;
}

export const createComment = async (
  args: CreateCommentArgs,
  context: { entities: { Comment: any; User: any; Post: any } }
) => {
  const { postId, authorUsername, content, parentId } = args;

  const author = await context.entities.User.findUnique({
    where: { username: authorUsername }
  });
  if (!author) {
    throw new Error(`User with username ${authorUsername} not found`);
  }

  const post = await context.entities.Post.findUnique({
    where: { id: postId }
  });
  if (!post) {
    throw new Error(`Post with id ${postId} not found`);
  }

  const newComment = await context.entities.Comment.create({
    data: {
      content,
      postId,
      authorId: author.id,
      parentId: parentId || null
    }
  });

  return newComment;
};

export const deleteComment = async (
  args: DeleteCommentArgs,
  context: { entities: { Comment: any } }
) => {
  const { commentId } = args;

  const comment = await context.entities.Comment.findUnique({
    where: { id: commentId }
  });

  if (comment) {
    await context.entities.Comment.delete({
      where: { id: commentId }
    });
  }

  return { success: true };
};

